// site/wiki/figures.mjs — GENERATED FIGURES for wiki articles.
//
// A wiki page writes `[[Figure:name|caption]]` and gets a real diagram. The diagram is DRAWN from data
// in code, not fetched and not generated by an image model, for three reasons:
//   • it has to be right — a diagram that teaches a wrong diagnosis is worse than no diagram;
//   • it has to be the same every time, so a page does not change meaning between loads;
//   • it has to be readable at any size and in print, which means SVG rather than pixels.
// Image-model art has its place elsewhere and is unchanged by this file: the Studio, the image pool, the
// animation lab, the remakes gallery and Hathor Metatron all keep generating exactly as before. This
// module covers WIKI FIGURES ONLY — the instructional diagrams inside library articles, which have to be
// correct and therefore are not guessed.
//
// Adding a figure: write a function that returns an SVG string, register it in FIGURES, done.
//
//   import { figureHtml, renderFigures, FIGURES, hasFigure } from './figures.mjs'

import { chartSvg } from '../../integrations/plant-deficiency-chart.mjs';
import { wheelSvg, wheelNames } from '../../integrations/aroma-wheel.mjs';
import { table, GRAPHENE_MATRIX } from '../../integrations/chain-compare.mjs';
import { specsTable, SPEC_DIMENSIONS } from '../../integrations/token-specs.mjs';

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
));
const f = (n) => Math.round(n * 100) / 100;

const FONT = 'system-ui,-apple-system,Segoe UI,sans-serif';
const INK = '#1d1b17', MUT = '#6b665c', LINE = '#ddd6c8', PAPER = '#f6f4ef';

const text = (x, y, s, { size = 12, weight = 400, anchor = 'middle', fill = INK, style = '' } = {}) =>
  `<text x="${f(x)}" y="${f(y)}" text-anchor="${anchor}" font-family="${FONT}" font-size="${size}" font-weight="${weight}" fill="${fill}"${style ? ` style="${style}"` : ''}>${esc(s)}</text>`;

const frame = (w, h, title, subtitle, body) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${esc(title)}">`
  + `<rect width="${w}" height="${h}" fill="${PAPER}"/>`
  + text(w / 2, 28, title, { size: 17, weight: 800 })
  + (subtitle ? text(w / 2, 48, subtitle, { size: 12, fill: MUT }) : '')
  + body + '</svg>';

// ── the perfumer's note pyramid ─────────────────────────────────────────────────────────────────────
export function notePyramid() {
  const w = 680, h = 400;
  const tiers = [
    { label: 'TOP', when: 'minutes', what: 'citrus, light aldehydes, bergamot, mint', y: 80, wid: 180, fill: '#e9c46a' },
    { label: 'HEART', when: 'hours', what: 'rose, jasmine, spice, geranium', y: 170, wid: 320, fill: '#c2846a' },
    { label: 'BASE', when: 'days', what: 'woods, resins, musks, vanilla, orris', y: 260, wid: 460, fill: '#7a5c45' },
  ];
  const body = tiers.map((t) => {
    const x = w / 2 - t.wid / 2;
    return `<rect x="${f(x)}" y="${t.y}" width="${t.wid}" height="72" rx="8" fill="${t.fill}" opacity="0.9"/>`
      + text(w / 2, t.y + 28, `${t.label} — ${t.when}`, { size: 14, weight: 800, fill: '#1d1b17' })
      + text(w / 2, t.y + 50, t.what, { size: 11.5, fill: '#2b2721' });
  }).join('')
    + `<path d="M 60,86 L 60,326" stroke="${MUT}" stroke-width="1.5" marker-end="url(#ar)"/>`
    + text(44, 206, 'evaporates', { size: 11, fill: MUT, anchor: 'middle', style: 'writing-mode:tb' })
    + text(w / 2, 352, 'A blend judged at the moment of mixing is judged on its top notes alone.', { size: 12, fill: MUT })
    + text(w / 2, 372, 'Perfumers evaluate on a blotter over hours and days — the dry-down.', { size: 12, fill: MUT });
  return frame(w, h, 'The note pyramid', 'Volatility decides when you meet a material — and for how long',
    `<defs><marker id="ar" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="${MUT}"/></marker></defs>${body}`);
}

// ── odour thresholds on a log scale ─────────────────────────────────────────────────────────────────
export function thresholdScale() {
  const w = 760, h = 330;
  // concentration in parts per billion; log10 scale
  const items = [
    { n: 'Grapefruit mercaptan', ppb: 1e-4, c: '#b3261e' },
    { n: 'β-Damascenone (rose)', ppb: 2e-3, c: '#b3261e' },
    { n: 'Geosmin (rain on soil)', ppb: 5e-3, c: '#8a4a28' },
    { n: 'Bell-pepper pyrazine', ppb: 2e-3, c: '#8a4a28' },
    { n: 'Vanillin', ppb: 20, c: '#2f6bb3' },
    { n: 'Linalool', ppb: 6, c: '#2f6bb3' },
    { n: 'Limonene', ppb: 200, c: '#3f8046' },
    { n: 'Ethanol', ppb: 1e8, c: '#3f8046' },
  ].sort((a, b) => a.ppb - b.ppb);
  const lo = -5, hi = 9;                                   // log10 ppb range
  const x0 = 210, x1 = w - 30;
  const X = (ppb) => x0 + (Math.log10(ppb) - lo) / (hi - lo) * (x1 - x0);
  const rows = items.map((it, i) => {
    const y = 90 + i * 27;
    return `<line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="${LINE}" stroke-width="1"/>`
      + `<circle cx="${f(X(it.ppb))}" cy="${y}" r="6" fill="${it.c}"/>`
      + text(x0 - 10, y + 4, it.n, { size: 11.5, anchor: 'end' });
  }).join('');
  const ticks = [-4, -2, 0, 2, 4, 6, 8].map((e) => {
    const x = x0 + (e - lo) / (hi - lo) * (x1 - x0);
    return `<line x1="${f(x)}" y1="78" x2="${f(x)}" y2="${90 + items.length * 27 - 14}" stroke="${LINE}" stroke-dasharray="2 3"/>`
      + text(x, 72, `10${sup(e)}`, { size: 10.5, fill: MUT });
  }).join('');
  return frame(w, h, 'Odour thresholds span twelve orders of magnitude',
    'parts per billion needed before a human nose detects it — note the scale is logarithmic',
    ticks + rows
    + text(w / 2, h - 26, 'This is why blending by weight, without regard to threshold, goes wrong.', { size: 12, fill: MUT })
    + text(w / 2, h - 9, 'A trace of a thiol will rule a mixture that is mostly terpene.', { size: 12, fill: MUT }));
}
const sup = (e) => String(e).replace(/-/g, '⁻').replace(/[0-9]/g, (d) => '⁰¹²³⁴⁵⁶⁷⁸⁹'[+d]);

