// ── the methylation cycle, as the Amplification Framework describes it ──────────────────────────────
// Folate → 5-MTHF → (BH4 regeneration) → the three hydroxylases → serotonin, dopamine, noradrenaline.
// Drawn to match the operator's own papers (L-Methylfolate; The Amplification Framework), where the
// point is that L-methylfolate acts on the COFACTOR, not the precursor — which is why precursor
// loading (tryptophan, tyrosine) does not do the same thing.
export function methylationCycle() {
  const w = 780, h = 430;
  const box = (x, y, bw, bh, label, sub, fill) =>
    `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="10" fill="${fill}" stroke="${MUT}"/>`
    + text(x + bw / 2, y + (sub ? bh / 2 - 2 : bh / 2 + 4), label, { size: 12.5, weight: 700 })
    + (sub ? text(x + bw / 2, y + bh / 2 + 15, sub, { size: 10.5, fill: MUT }) : '');
  const arrow = (x1, y1, x2, y2, label) =>
    `<path d="M ${x1},${y1} L ${x2},${y2}" stroke="${MUT}" stroke-width="1.8" marker-end="url(#mc)"/>`
    + (label ? text((x1 + x2) / 2, (y1 + y2) / 2 - 6, label, { size: 10, fill: MUT }) : '');
  const body = [
    box(30, 80, 120, 46, 'Dietary folate', '', '#eef3e8'),
    arrow(150, 103, 196, 103, ''),
    box(196, 80, 120, 46, 'MTHFR', 'C677T slows this', '#f6e9c8'),
    arrow(316, 103, 362, 103, ''),
    box(362, 72, 150, 62, 'L-methylfolate', '5-MTHF · crosses the BBB', '#dfeaf6'),
    // down to BH4
    arrow(437, 134, 437, 176, ''),
    box(352, 176, 170, 56, 'BH4 regenerated', 'made · protected · recycled', '#e6f0e4'),
    // the three hydroxylases
    arrow(437, 232, 437, 268, ''),
    box(282, 268, 310, 46, 'Tryptophan · tyrosine · phenylalanine hydroxylase', 'BH4 is the rate-limiting cofactor for all three', '#fff'),
    arrow(437, 314, 437, 348, ''),
    box(300, 348, 274, 46, 'Serotonin · dopamine · noradrenaline', '', '#f3e3ef'),
    // homocysteine arm
    arrow(422, 103, 560, 103, ''),
    box(560, 80, 190, 46, 'Homocysteine → methionine', 'needs B12 — no B12, no use', '#f6e3e3'),
    arrow(655, 126, 655, 166, ''),
    box(590, 166, 130, 46, 'SAM-e', 'the methyl donor', '#efe8f6'),
    text(655, 236, 'DNA methylation,', { size: 10.5, fill: MUT }),
    text(655, 250, 'BDNF, myelination', { size: 10.5, fill: MUT }),
  ].join('');
  return frame(w, h, 'Where L-methylfolate acts', 'It supplies the COFACTOR, not the precursor — which is why loading tryptophan or tyrosine is not the same thing',
    `<defs><marker id="mc" markerWidth="9" markerHeight="9" refX="7" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="${MUT}"/></marker></defs>${body}`
    + text(w / 2, h - 10, 'Check B12 before loading folate: folate corrects the anaemia of B12 deficiency without correcting the nerve damage.', { size: 11, fill: '#b3261e' }));
}

// ── the Graphene family matrix ──────────────────────────────────────────────────────────────────────
// STEEM, HIVE, BLURT, MELEK side by side, plus PRANA and the side tokens — drawn from
// integrations/chain-compare.mjs so the facts live in one place and the picture cannot drift from them.
// Side tokens are shaded differently on purpose: VKBT and CURE are NOT chains, and a matrix that lines
// them up with Steem without saying so would teach the wrong thing.
export function grapheneMatrix() {
  const t = table(GRAPHENE_MATRIX);
  const cols = t.chains.length;
  const labelW = 150, colW = 132, rowH = 64, headH = 54;
  const w = labelW + cols * colW, h = 96 + headH + t.rows.length * rowH + 30;
  const TOKEN = new Set(['vkbt', 'cure']);
  const wrap = (str, max) => {
    const words = String(str).split(' '); const lines = []; let cur = '';
    for (const word of words) {
      if ((cur + ' ' + word).trim().length > max) { if (cur) lines.push(cur); cur = word; } else cur = (cur + ' ' + word).trim();
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 4);
  };
  let body = '';
  t.chains.forEach((c, i) => {
    const x = labelW + i * colW;
    const token = TOKEN.has(c.id);
    body += `<rect x="${x}" y="88" width="${colW - 2}" height="${headH - 4}" rx="8" fill="${token ? '#e8e0ef' : '#dfe9f3'}" stroke="${LINE}"/>`
      + text(x + colW / 2, 112, c.name, { size: 14, weight: 800 })
      + text(x + colW / 2, 128, token ? 'side token' : 'chain', { size: 10, fill: MUT });
  });
  t.rows.forEach((r, ri) => {
    const y = 96 + headH + ri * rowH;
    body += `<rect x="0" y="${y}" width="${w}" height="${rowH - 3}" rx="6" fill="${ri % 2 ? '#ffffff' : '#f1ece1'}"/>`
      + text(10, y + rowH / 2 + 4, r.label, { size: 12, weight: 700, anchor: 'start' });
    r.values.forEach((v, ci) => {
      const x = labelW + ci * colW;
      wrap(v, 22).forEach((line, li) => {
        body += text(x + colW / 2, y + 18 + li * 12, line, { size: 9.5, fill: INK });
      });
    });
  });
  return frame(w, h, 'The Graphene family, side by side',
    'One codebase, several chains — and two things that are not chains at all',
    body + text(w / 2, h - 10, 'VKBT and CURE are engine side tokens: they inherit the security and consensus of whatever chain hosts them.', { size: 11, fill: MUT }));
}

// ── token SPECS matrix ──────────────────────────────────────────────────────────────────────────────
// The right peer group for a side token is OTHER SIDE TOKENS, compared on tokenomics — supply, holders,
// concentration, emission, venue, activity, cap. Numbers come from integrations/token-specs.mjs and an
// unsourced figure renders as "—" rather than a guess.
export function tokenSpecsMatrix() {
  const t = specsTable(['vkbt', 'cure', 'pob', 'bbh', 'blurt']);
  const cols = t.tokens.length;
  const labelW = 148, colW = 150, rowH = 58, headH = 58;
  const wrap = (str, max) => {
    const words = String(str).split(' '); const lines = []; let cur = '';
    for (const word of words) {
      if ((cur + ' ' + word).trim().length > max) { if (cur) lines.push(cur); cur = word; } else cur = (cur + ' ' + word).trim();
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 3);
  };
  const w = labelW + cols * colW, h = 96 + headH + t.rows.length * rowH + 76;
  let body = '';
  t.tokens.forEach((tok, i) => {
    const x = labelW + i * colW;
    const premium = tok.id === 'vkbt' || tok.id === 'cure';
    body += `<rect x="${x}" y="88" width="${colW - 2}" height="${headH - 4}" rx="8" fill="${premium ? '#e4dcc4' : '#e8e8e8'}" stroke="${LINE}"/>`
      + text(x + colW / 2, 110, tok.name, { size: 14, weight: 800 })
      + text(x + colW / 2, 126, premium ? 'premium — bought, given away' : 'tradeable / fuel', { size: 9, fill: MUT })
      + text(x + colW / 2, 139, tok.layer.replace('Hive-Engine ', '').replace('Chain coin, wrapped onto Hive-Engine', 'chain coin (wrapped)'), { size: 8.5, fill: MUT });
  });
  t.rows.forEach((r, ri) => {
    const y = 96 + headH + ri * rowH;
    body += `<rect x="0" y="${y}" width="${w}" height="${rowH - 3}" rx="6" fill="${ri % 2 ? '#ffffff' : '#f1ece1'}"/>`
      + text(10, y + rowH / 2 + 4, r.label, { size: 12, weight: 700, anchor: 'start' });
    r.values.forEach((v, ci) => {
      const lines = wrap(v, 20);
      const top = y + rowH / 2 - (lines.length - 1) * 6 + 3;
      lines.forEach((line, li) => {
        body += text(labelW + ci * colW + colW / 2, top + li * 12, line, { size: 10, fill: v === '—' ? MUT : INK });
      });
    });
  });
  const foot = 96 + headH + t.rows.length * rowH + 20;
  return frame(w, h, 'Token specs — the comparison that actually applies',
    'A side token is not a chain. Its peers are other Hive-Engine tokens, and the dimensions are tokenomics.',
    body
    + text(w / 2, foot, 'Supply alone means nothing; holders alone means nothing. The pair matters, and concentration decides whether to trust it.', { size: 11, fill: INK })
    + text(w / 2, foot + 17, 'The VKF position in VKBT and CURE was PURCHASED at market, not allocated — and is being given away through curation programs.', { size: 11, fill: MUT })
    + text(w / 2, foot + 36, '"—" means not recorded here, never a guess. Live figures belong to a Hive-Engine read.', { size: 10.5, fill: MUT }));
}

